var t=`0246-kolokithokeftedes`;var n=`world-0246`;var o=`GR`;var s=`southern-europe`;var a=4;var l=32;var r={en:`Kolokithokeftedes`,ua:`Кабачкові котлетки`};var g={en:`A traditional Greece dish made with zucchini, feta, chicken egg, all-purpose flour. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: цукіні, фета, куряче яйце, пшеничне борошно універсальне. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:8,i:[[`zucchini`,650,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`feta`,180,`g`],[`chicken-egg`,2,`pcs`],[`all-purpose-flour`,95,`g`],[`dill`,24,`g`],[`mint`,15,`g`],[`green-onion`,90,`g`],[`table-salt`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`extra-virgin-olive-oil`,80,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`plain-yogurt`,120,`g`]]}];var d={slug:t,id:n,country:`GR`,region:s,servings:4,minutes:32,title:r,text:g,steps:u};export{o as country,d as default,n as id,l as minutes,s as region,a as servings,t as slug,u as steps,g as text,r as title};